**`stub-provider.mjs`**

```js
// Stub OpenAI-compatible provider. Records every request body. The latest user
// message selects a probe:
//   PROBE-DIRECT  -> call `read` on the skill file, then reply.
//   PROBE-NESTED  -> call `tool_call` { id: "read" } on the skill file, then reply.
//   PROBE-HISTORY -> call `tool_call` { id: "sessions_history", includeTools }, then reply.
import { appendFileSync } from "node:fs";
import { createServer } from "node:http";

const port = Number(process.argv[2]);
const logPath = process.argv[3];
const skillPath = process.env.STUB_SKILL_PATH ?? "";
let completions = 0;

function latestUserText(messages) {
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    const message = messages[index];
    if (message?.role !== "user") continue;
    const content = message.content;
    const text =
      typeof content === "string"
        ? content
        : Array.isArray(content)
          ? content.map((part) => (typeof part?.text === "string" ? part.text : "")).join("")
          : "";
    // Newer builds append a runtime-context user message after the real prompt.
    if (!text.includes("PROBE-")) continue;
    return { index, text };
  }
  return { index: -1, text: "" };
}

function plannedCall(probe) {
  if (probe === "PROBE-DIRECT") return { name: "read", args: { path: skillPath } };
  if (probe === "PROBE-NESTED") return { name: "tool_call", args: { id: "read", args: { path: skillPath } } };
  if (probe === "PROBE-HISTORY") {
    return {
      name: "tool_call",
      args: { id: "sessions_history", args: { sessionKey: "agent:main:main", includeTools: true } },
    };
  }
  return undefined;
}

const server = createServer(async (req, res) => {
  const chunks = [];
  for await (const chunk of req) chunks.push(chunk);
  const raw = Buffer.concat(chunks).toString("utf8");
  let body;
  try {
    body = raw ? JSON.parse(raw) : undefined;
  } catch {
    body = raw;
  }
  if (req.method === "GET" && req.url?.endsWith("/models")) {
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify({ object: "list", data: [{ id: "stub-model", object: "model" }] }));
    return;
  }
  if (req.method !== "POST" || !req.url?.endsWith("/chat/completions")) {
    res.writeHead(404).end();
    return;
  }
  completions += 1;
  const messages = Array.isArray(body?.messages) ? body.messages : [];
  const offered = (body?.tools ?? []).map((tool) => tool?.function?.name).filter(Boolean);
  const user = latestUserText(messages);
  const probe = ["PROBE-DIRECT", "PROBE-NESTED", "PROBE-HISTORY"].find((name) =>
    user.text.includes(name),
  );
  const answered = messages.slice(user.index + 1).some((message) => message?.role === "tool");
  const call = !answered && probe ? plannedCall(probe) : undefined;
  const callable = call && offered.includes(call.name);
  appendFileSync(
    logPath,
    JSON.stringify({ at: Date.now(), n: completions, probe, answered, offered, call: callable ? call : undefined, body }) + "\n",
  );
  const model = body?.model ?? "stub-model";
  const frame = (delta, finish) =>
    `data: ${JSON.stringify({
      id: `stub-${completions}`,
      object: "chat.completion.chunk",
      created: Math.floor(Date.now() / 1000),
      model,
      choices: [{ index: 0, delta, finish_reason: finish }],
      ...(finish ? { usage: { prompt_tokens: 10, completion_tokens: 2, total_tokens: 12 } } : {}),
    })}\n\n`;
  res.writeHead(200, { "content-type": "text/event-stream", "cache-control": "no-cache" });
  if (callable) {
    res.write(
      frame(
        {
          role: "assistant",
          content: null,
          tool_calls: [
            {
              index: 0,
              id: `call_${probe.toLowerCase().replace(/[^a-z]/g, "_")}_${completions}`,
              type: "function",
              function: { name: call.name, arguments: JSON.stringify(call.args) },
            },
          ],
        },
        null,
      ),
    );
    res.write(frame({}, "tool_calls"));
  } else {
    res.write(frame({ role: "assistant", content: `Done (${probe ?? "no probe"}).` }, null));
    res.write(frame({}, "stop"));
  }
  res.end("data: [DONE]\n\n");
});
server.listen(port, "127.0.0.1", () => console.log(`stub provider on ${port}`));
