```ts
// Backend client: `turn <message>` runs one chat turn; `history` prints chat.history tool results
// (top-level toolResult messages and tool-result blocks nested in other messages).
import { randomUUID } from "node:crypto";

const repo = process.env.REPO_DIR;
const { GatewayClient } = await import(`${repo}/packages/gateway-client/src/index.ts`);

const url = process.env.GW_URL ?? "";
const token = process.env.GW_TOKEN ?? "";
const [mode, message] = process.argv.slice(2);
const sessionKey = "agent:main:main";

let finals = 0;
let helloResolve: () => void;
const hello = new Promise<void>((resolve) => (helloResolve = resolve));
const client = new GatewayClient({
  url,
  token,
  clientName: "gateway-client",
  mode: "backend",
  deviceIdentity: null,
  scopes: ["operator.admin"],
  onHelloOk: () => helloResolve(),
  onEvent: (evt: { event: string; payload?: { state?: string } }) => {
    if (evt.event === "chat" && ["final", "error", "aborted"].includes(evt.payload?.state ?? "")) {
      finals += 1;
      console.log(`chat ${evt.payload?.state}`);
    }
  },
  onConnectError: (err: Error) => console.error("connect error", err.message),
});
client.start();
await hello;

// The Gateway listens before agent databases finish startup inspection; honor retryable errors.
async function request(method: string, params: Record<string, unknown>): Promise<unknown> {
  const deadline = Date.now() + 120_000;
  for (;;) {
    try {
      return await client.request(method, params);
    } catch (error) {
      const retry = error as { retryable?: boolean; retryAfterMs?: number };
      if (!retry.retryable || Date.now() > deadline) throw error;
      await new Promise((resolve) => setTimeout(resolve, retry.retryAfterMs ?? 250));
    }
  }
}

if (mode === "turn") {
  await request("chat.send", { idempotencyKey: randomUUID(), sessionKey, message });
  const deadline = Date.now() + 120_000;
  while (finals < 1) {
    if (Date.now() > deadline) throw new Error("timed out waiting for the final chat event");
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
} else {
  const history = (await request("chat.history", { sessionKey, limit: 100 })) as {
    messages?: Array<Record<string, unknown>>;
  };
  const rows: unknown[] = [];
  for (const entry of history.messages ?? []) {
    if (entry.role === "toolResult") {
      rows.push({ kind: "toolResult", toolName: entry.toolName, toolCallId: entry.toolCallId, details: entry.details });
    } else if (Array.isArray(entry.content)) {
      for (const block of entry.content as Array<Record<string, unknown>>) {
        if (block?.type === "toolResult") {
          rows.push({
            kind: `nested in ${String(entry.role)}${entry.customType ? `:${String(entry.customType)}` : ""}`,
            toolName: block.toolName,
            toolCallId: block.toolCallId,
            details: block.details,
          });
        }
      }
    }
  }
  console.log(`chat.history tool results (${rows.length}):`);
  console.log(JSON.stringify(rows, null, 2));
}
await client.stopAndWait();
process.exit(0);
